constraints:
1<=M<=N<=10^{6}

expected time complexity: O(N*sqrt(N))
expected auxiliary space: O(1)

standard_solution_code:
class Solution:

	def isprime(self, n):
		if n == 1:
			return False
		for i in range(2, int(n ** 0.5) + 1):
			if n % i == 0:
				return False
		return True

	def primeRange(self, M, N):
		l = []
		for i in range(M, N + 1, 1):
			if self.isprime(i):
				l.append(i)
		return l
